            Ok(None) => true,
            Err(msg) => {
                eprintln!("Error: {}", msg);
                return Err(1);
            }
        }
    };
    // trim.updateInterval
    let interval: u64 = if let Some(v) = cli_interval {
        v
    } else {
        match get_i64("trim.updateInterval") {
            Ok(Some(v)) => {
                if v < 0 {
                    // panic to match original
                    // Need to panic at src/config.rs:318:9 with message
                    // We will manually print panic message and exit 101 to match, including tid?
                    // Instead, use panic! with file override? We can create src/config.rs with panic at line 318.
