fn prompt_confirm() -> Option<bool> {
    use std::io::{Read, Write};
    // Write prompt to stderr with escapes
    let mut err = std::io::stderr();
    // Original sequence: "Confirm? [y/N] " + hide + "\r" + clear + "Confirm? yes/no" + "\r\n" + show?
    // Actually steps:
    // 1. Print "Confirm? [y/N] " to stderr
    // 2. Hide cursor: ESC[?25l
    // 3. Read line from /dev/tty
    // 4. Clear line: \r + ESC[2K?
    // 5. Print "Confirm? yes" or "Confirm? no" + "\r\n"
    // 6. Show cursor: ESC[?25h
    // Let's replicate exactly as observed hex:
    // "Confirm? [y/N] " + ESC[?25l + "\r" + ESC[2K + "Confirm? yes" + "\r\n" + ESC[?25h(+ "Cancelled" or push etc. to stdout? No, prompt all to stderr, result to stdout? Actually "Cancelled" to stdout, "Confirm? yes/no" to stderr.
    // Observed: prompt "Confirm? [y/N] " + hide + "\r" + clear + "Confirm? yes" + "\r\n" + show
    // For "no": "Confirm? [y/N] " + hide + "\r" + clear + "Confirm? no" + "\r\n" + show + "Cancelled" to stdout?
    // Actually "Cancelled" was to stdout (as we saw with stdout redirect). Good.
    // So prompt parts to stderr, Cancelled to stdout.
    err.write_all(b"Confirm? [y/N] ").ok()?;
    err.write_all(b"\x1b[?25l").ok()?;
    err.flush().ok()?;
    // Read from /dev/tty
    let mut tty = std::fs::OpenOptions::new().read(true).write(true).open("/dev/tty").ok()?;
    // Need to read a line? Dialoguer reads a line with editing? It reads input with prompt? For our purposes, read line up to \n.
    // The input echo is handled by terminal (pty), not by us. We just read.
    let mut buf = String::new();
    // Use BufRead?
    use std::io::BufRead;
    let mut reader = std::io::BufReader::new(&mut tty);
    // Read line? If EOF, return None?
    let n = reader.read_line(&mut buf).ok()?;
    if n == 0 {
        // EOF
        // Need to still print clear + no + show?
        err.write_all(b"\r\x1b[2KConfirm? no\r\n").ok()?;
        err.write_all(b"\x1b[?25h").ok()?;
        err.flush().ok()?;
        return Some(false);
    }
    let trimmed = buf.trim().to_ascii_lowercase();
    let is_yes = trimmed == "y" || trimmed == "yes";
    if is_yes {
        err.write_all(b"\r\x1b[2KConfirm? yes\r\n").ok()?;
        err.write_all(b"\x1b[?25h").ok()?;
        err.flush().ok()?;
        Some(true)
    } else {
        err.write_all(b"\r\x1b[2KConfirm? no\r\n").ok()?;
        err.write_all(b"\x1b[?25h").ok()?;
        err.flush().ok()?;
        Some(false)
    }
}

fn get_commit_short_subject(repo: &git2::Repository, branch: &str) -> (String, String) {
    // Get commit for branch
    if let Ok(r) = repo.find_branch(branch, git2::BranchType::Local) {
        if let Ok(resolved) = r.get().resolve() {
            if let Some(oid) = resolved.target() {
                if let Ok(commit) = repo.find_commit(oid) {
                    let short = format!("{:.7}", oid.to_string());
                    // Actually short is 7 chars of oid hex? Use oid.to_string()[..7]
                    let msg = commit.summary().unwrap_or("").to_string();
                    return (short, msg);
                }
            }
        }
        // Fallback via revparse?
        if let Ok(obj) = repo.revparse_single(&format!("refs/heads/{}", branch)) {
            let oid = obj.id();
            let short = oid.to_string()[..7].to_string();
            if let Ok(commit) = repo.find_commit(oid) {
                let msg = commit.summary().unwrap_or("").to_string();
                return (short, msg);
            }
            return (short, "".to_string());
        }
    }
    ("unknown".to_string(), "".to_string())
}

fn get_local_branches(repo: &git2::Repository) -> Vec<(String, Option<String>, git2::Oid)> {
    let mut res = Vec::new();
    if let Ok(iter) = repo.branches(Some(git2::BranchType::Local)) {
        for b in iter {
            if let Ok((br, _)) = b {
                if let Ok(name) = br.name() {
                    if let Some(n) = name {
                        let name_str = n.to_string();
                        // Get oid
                        let oid = br.get().resolve().ok().and_then(|r| r.target()).or_else(|| br.get().target()).unwrap_or(git2::Oid::zero());
                        // Get upstream full ref if exists (via branch.upstream, which fails if gone)
                        let up_full: Option<String> = br.upstream().ok().and_then(|up| up.name().unwrap_or(None).map(|s| s.to_string()));
                        // For gone, up_full will be None here, but we handle via config later. For now, store None and let caller handle via config.
                        // Actually for gone, branch.upstream() returns Err (not found), so None. Good.
                        res.push((name_str, up_full, oid));
                    }
                }
            }
        }
    }
    res
}

fn get_remote_branches(repo: &git2::Repository) -> Vec<(String, String, git2::Oid)> {
    let mut res = Vec::new();
    if let Ok(iter) = repo.branches(Some(git2::BranchType::Remote)) {
        for b in iter {
            if let Ok((br, _)) = b {
                if let Ok(name) = br.name() {
                    if let Some(n) = name {
                        // Exclude symbolic refs like origin/HEAD? br.get().is_symbolic()? Check via reference?
                        // Use br.get() reference
                        let refr = br.get();
                        if refr.is_symbolic() {
                            continue;
                        }
                        // Also exclude if name ends with /HEAD? e.g., origin/HEAD
                        if n.ends_with("/HEAD") {
                            continue;
                        }
                        let full = refr.name().unwrap_or("").to_string();
                        let oid = refr.resolve().ok().and_then(|r| r.target()).or_else(|| refr.target()).unwrap_or(git2::Oid::zero());
                        res.push((n.to_string(), full, oid));
                    }
                }
            }
        }
    }
    res
}

fn is_ancestor(repo: &git2::Repository, ancestor: git2::Oid, descendant: git2::Oid) -> bool {
    if ancestor == descendant {
        return true;
    }
    match repo.graph_descendant_of(descendant, ancestor) {
        Ok(v) => v,
        Err(_) => false,
    }
}

