            return false;
        }
        for boid in &base_oids {
            if oid == *boid {
                return true;
            }
            // Fast path: ancestor check via graph
            if let Ok(true) = repo.graph_descendant_of(*boid, oid) {
                return true;
            }
            // Slow path: git cherry to detect patch-equivalent (rebased) merges
            let out = std::process::Command::new("git").arg("cherry").arg(boid.to_string()).arg(oid.to_string()).output();
            if let Ok(o) = out {
                if o.status.success() {
                    let s = String::from_utf8_lossy(&o.stdout);
                    // If no '+' lines, then merged (all '-' or empty)
                    let mut has_plus = false;
                    for line in s.lines() {
                        let line = line.trim();
                        if line.starts_with('+') {
                            has_plus = true;
                            break;
                        }
                    }
                    if !has_plus {
                        return true;
                    }
                }
            }
        }
        false
    };"""
t = t.replace(old, new)
