                    Ok(None)
                } else {
                    Err(e.to_string())
                }
            }
        }
    };"""
new = """    let get_bool = |key: &str| -> Result<Option<bool>, String> {
        match cfg.get_bool(key) {
            Ok(v) => Ok(Some(v)),
            Err(e) => {
                if e.code() == git2::ErrorCode::NotFound {
                    Ok(None)
                } else {
                    let mut msg = e.to_string();
                    // libgit2 version difference: original says "as a boolean value", newer says "as a boolean"
                    if msg.contains("as a boolean;") {
                        msg = msg.replace("as a boolean;", "as a boolean value;");
                    } else if msg.contains("as a boolean value;") {
                        // already correct
                    } else if msg.contains("as a boolean") {
                        // Fallback: ensure value
                        msg = msg.replace("as a boolean", "as a boolean value");
                    }
                    Err(msg)
                }
            }
        }
    };"""
t = t.replace(old, new)
p.write_text(t)
print("fixed bool")
